export const QUIZ_ITEMS = [
  { id: "1465", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام ابن تيمية؟ وما أبرز مؤلفاته؟", answer: "هو شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني الحنبلي (661-728هـ). وُلد في حرّان وعاش في دمشق. أبرز مؤلفاته: «درء تعارض العقل والنقل»، «منهاج السنة النبوية»، «الفتاوى الكبرى»، «الاستقامة»، «اقتضاء الصراط المستقيم». اشتُهر بالتجديد في مسائل العقيدة والرد على الفلسفة الكلامية وعلى الغلو والبدع.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1466", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما الفرق بين «الإسناد» و«المتن» في علم الحديث؟", answer: "الإسناد (السند): هو سلسلة الرواة الذين نقلوا الحديث من راوٍ إلى آخر حتى وصل إلى النبي ﷺ. والمتن: هو نص الحديث ومضمونه الذي قاله النبي ﷺ أو فعله. الحكم على الحديث صحةً وضعفاً يعتمد في الأساس على دراسة الإسناد (رجاله وعلله)، ثم دراسة المتن للكشف عن الشذوذ والنكارة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1467", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام النووي؟ وما أبرز مؤلفاته؟", answer: "هو الإمام يحيى بن شرف النووي الشافعي (631-676هـ)، من أكبر علماء الإسلام وأتقاهم. وُلد في نوى بسوريا. أبرز مؤلفاته: «رياض الصالحين» و«الأذكار» و«المنهاج في شرح صحيح مسلم» (المعروف بشرح النووي) و«المجموع شرح المهذب» و«الأربعون النووية». توفي وعمره 45 سنة لكنه ترك إرثاً علمياً ضخماً يُدرَّس حتى اليوم.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1468", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما المذاهب الفقهية الأربعة المعتمدة؟ ومن مؤسسوها؟", answer: "المذاهب الفقهية الأربعة: 1) الحنفي — مؤسسه الإمام أبو حنيفة النعمان (80-150هـ). 2) المالكي — مؤسسه الإمام مالك بن أنس (93-179هـ). 3) الشافعي — مؤسسه الإمام محمد بن إدريس الشافعي (150-204هـ). 4) الحنبلي — مؤسسه الإمام أحمد بن حنبل (164-241هـ). كل مذهب له منهجه في الاجتهاد والاستدلال، ويُعبّر عن فهم دقيق للنصوص الشرعية، والخلاف بينها رحمة وتوسعة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1469", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "سهل", question: "ما معنى اسم الله «الغفار» و«الغفور»؟ وما الفرق بينهما؟", answer: "الغفور: صيغة مبالغة تدل على عِظَم المغفرة وشمولها — أي أنه يغفر الذنب العظيم. الغفار: صيغة مبالغة تدل على تكرار المغفرة ودوامها — أي أنه يغفر مرة بعد مرة. فالغفور يشير إلى الكمية والعِظَم، والغفار يشير إلى التكرار والاستمرار. قال تعالى: ﴿إِنَّهُ كَانَ غَفَّاراً﴾ (نوح: 10) وقال: ﴿وَهُوَ الْغَفُورُ الرَّحِيمُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1470", section: "الأسماء الحسنى", category: "الأسماء الحسنى", level: "متوسط", question: "ما معنى اسم الله «القيوم»؟ وما دلالته الاعتقادية؟", answer: "القيوم: من قام يقوم — صيغة مبالغة تجمع معنيين: 1) القائم بنفسه: أي الغني عن كل شيء الذي لا يحتاج لأحد في وجوده. 2) المُقيم لغيره: أي الذي يقوم على كل مخلوق فيحفظه ويرزقه ويُدبّره. الدلالة الاعتقادية: استقلال الله التام عن خلقه، وحاجة المخلوقات جميعاً إليه. ولذا جُمع مع «الحي» في آية الكرسي: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾.", explanation: "يُستفاد منه في باب الأسماء الحسنى. يُستفاد منه في باب الأسماء الحسنى مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1471", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما أركان الحج؟", answer: "الإحرام والوقوف بعرفة وطواف الإفاضة والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1472", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما الميقات المكاني لأهل المدينة النبوية؟", answer: "ذو الحُلَيفة (أبيار علي)، ويُحرم منه أهل المدينة ومن مرّ به من غيرهم، وهو أبعد المواقيت عن مكة", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1473", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما طواف الإفاضة؟", answer: "طواف الإفاضة (طواف الزيارة): ركن من أركان الحج لا يصحّ الحج بتركه ولا يُجبر بدم — بخلاف الواجب الذي يُجبر بدم — ووقته يوم النحر وما بعده، بعد الوقوف بعرفة. وأصله قوله تعالى: ﴿وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ﴾ (الحج: ٢٩)", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1474", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "كم عدد أشواط السعي بين الصفا والمروة؟", answer: "سبعة أشواط، يبدأ بالصفا وينتهي بالمروة؛ فالذهاب من الصفا إلى المروة شوط، والرجوع من المروة إلى الصفا شوط ثانٍ", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1475", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما معنى الإحرام؟", answer: "نية الدخول في النسك (الحج أو العمرة). والتلبية عندها سنة مؤكدة عند الشافعية والحنابلة، وواجب عند المالكية، وشرطٌ لانعقاد الإحرام عند الحنفية فلا ينعقد عندهم إلا بها أو بما يقوم مقامها", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1476", section: "الحج والعمرة", category: "الحج", level: "صعب", question: "ما الفرق بين القِران والتمتّع والإفراد في الحج؟", answer: "القِران: أن يُحرم بالحج والعمرة معًا بإحرام واحد. التمتّع: أن يُحرم بالعمرة أولاً فيتحلّل منها، ثم يُحرم بالحج في عامه. الإفراد: أن يُحرم بالحج وحده. ويلزم المتمتّع والقارن هَدْيٌ ولا هَدْيَ على المُفرِد، قال تعالى: ﴿فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ﴾ (البقرة: ١٩٦)", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1477", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما الإحصار في الحج؟", answer: "أن يُمنع المُحرِم من إتمام نسكه، فيتحلّل بنحر هَدْي، قال تعالى: ﴿فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ﴾ (البقرة: ١٩٦). وقصره المالكية والشافعية على المنع بالعدوّ، ووسّعه الحنفية فأدخلوا فيه المرض وذهاب النفقة والحبس ونحوها", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1478", section: "الحج والعمرة", category: "أركان الحج", level: "سهل", question: "ما أركان الحج الأساسية؟", answer: "الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب أركان الحج. يُستفاد منه في باب أركان الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1479", section: "الحج والعمرة", category: "مناسك الحج", level: "متوسط", question: "ما يوم عرفة ولماذا يُعدّ أهم أيام الحج؟", answer: "هو التاسع من ذي الحجة، وفيه الوقوف بعرفة الذي هو ركن الحج الأعظم، وصيامه يكفّر سنتين", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1480", section: "الحج والعمرة", category: "مناسك الحج", level: "سهل", question: "ما الإحرام في الحج؟", answer: "هو النية لأداء نسك الحج أو العمرة مع ترك المحظورات، ويبدأ من الميقات المحدد لكل جهة", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1481", section: "الحج والعمرة", category: "مناسك الحج", level: "صعب", question: "ما محظورات الإحرام؟", answer: "حلق الشعر، وتقليم الأظافر، ولبس المخيط للرجل، والطيب، والصيد، وعقد النكاح، والرفث", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1482", section: "الحج والعمرة", category: "رمي الجمرات", level: "متوسط", question: "متى تُرمى جمرة العقبة؟", answer: "ترمى وحدها يوم النحر (العاشر من ذي الحجة)، ثم تُرمى مرة أخرى مع الجمرتين الصغرى والوسطى في كل يوم من أيام التشريق الثلاثة بعد زوال الشمس", explanation: "يُستفاد منه في باب رمي الجمرات. يُستفاد منه في باب رمي الجمرات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1483", section: "الحج والعمرة", category: "مواقيت الحج", level: "صعب", question: "ما مواقيت الحج الزمانية؟", answer: "شوال وذو القعدة وعشر من ذي الحجة، وهي أشهر الحج المذكورة في القرآن", explanation: "يُستفاد منه في باب مواقيت الحج. يُستفاد منه في باب مواقيت الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1484", section: "الحج والعمرة", category: "السعي", level: "سهل", question: "ما مكانة السعي بين الصفا والمروة؟", answer: "ركن من أركان الحج والعمرة لا يصح النسك بدونه، لقوله تعالى: ﴿إن الصفا والمروة من شعائر الله﴾", explanation: "يُستفاد منه في باب السعي. يُستفاد منه في باب السعي مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1485", section: "الحج والعمرة", category: "فريضة الحج", level: "سهل", question: "كم مرة حج النبي ﷺ؟ وما حجة الوداع؟", answer: "حج النبي ﷺ مرة واحدة بعد الهجرة وهي حجة الوداع عام 10هـ (632م)، وكان معه أكثر من مئة ألف من الصحابة. ألقى فيها خطبة الوداع الجامعة.", explanation: "يُستفاد منه في باب فريضة الحج. يُستفاد منه في باب فريضة الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1486", section: "الحج والعمرة", category: "مناسك الحج", level: "متوسط", question: "ما الفرق بين الحج المفرد والقِران والتمتع؟", answer: "المفرد: الإحرام بالحج وحده من الميقات. القِران: الإحرام بالحج والعمرة معاً. التمتع: الإحرام بالعمرة أولاً ثم التحلل منها ثم الإحرام بالحج في أشهره. والثلاثة جائزة بالإجماع، وأفضلها محل خلاف بين المذاهب: الحنابلة يرون التمتع أفضل، والمالكية والشافعية يرون الإفراد أفضل، والحنفية يرون القِران أفضل.", explanation: "يُستفاد منه في باب مناسك الحج. يُستفاد منه في باب مناسك الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1487", section: "الحج والعمرة", category: "أركان الحج", level: "متوسط", question: "ما أركان الحج التي لا يصح إلا بها؟", answer: "أركان الحج أربعة: 1- الإحرام (النية). 2- الوقوف بعرفة وهو أعظم الأركان («الحج عرفة»). 3- طواف الإفاضة (الزيارة). 4- السعي بين الصفا والمروة. وهذا مذهب الشافعية والحنابلة.", explanation: "يُستفاد منه في باب أركان الحج. يُستفاد منه في باب أركان الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1488", section: "الحج والعمرة", category: "الميقات", level: "متوسط", question: "ما ميقات أهل الكويت للحج والعمرة؟", answer: "ميقات أهل الكويت هو ذو الحليفة (أبيار علي) إذا مروا بطريق المدينة، أو ميقات قرن المنازل (السيل الكبير) إذا مروا بالطريق الشمالي السعودي الشرقي. وبعضهم يُحرم من الكويت إن نوى من الجو.", explanation: "يُستفاد منه في باب الميقات. يُستفاد منه في باب الميقات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1489", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما أركان الحج الأربعة؟ وما الفرق بين الركن والواجب؟", answer: "أركان الحج الأربعة: 1) الإحرام بنية الحج. 2) الوقوف بعرفة — وهو ركن الحج الأعظم. 3) طواف الإفاضة (الزيارة). 4) السعي بين الصفا والمروة. الفرق بين الركن والواجب: الركن — ما لا يصح الحج بتركه مطلقاً (لا يُجبر بدم). الواجب — ما يصح الحج بتركه ويُجبر بدم. والسنن — ما يُثاب على فعله ولا يُعاقب على تركه.", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1490", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما ترتيب أعمال يوم النحر (يوم العيد) في الحج؟", answer: "أعمال يوم النحر بالترتيب: 1) رمي جمرة العقبة الكبرى (بعد منتصف ليلة العيد أو بعد الفجر). 2) ذبح الهدي. 3) حلق الرأس أو التقصير — يرفع الإحرام الأول (إلا النساء والمحرم). 4) طواف الإفاضة (الحلُّ الكامل بعده). 5) السعي (من لم يسعَ بعد طواف القدوم). ويجوز التقديم والتأخير بين هذه الأعمال الثلاثة الأخيرة كما دلّت عليه الأحاديث.", explanation: "يُستفاد منه في باب الحج. يُستفاد منه في باب الحج مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1491", section: "الصحابة", category: "الخلفاء", level: "متوسط", question: "من أول الخلفاء الراشدين؟", answer: "أبو بكر الصديق رضي الله عنه — أول الخلفاء الراشدين، وأول الرجال إسلاماً بعد جبريل.", explanation: "يُستفاد منه في باب الخلفاء. يُستفاد منه في باب الخلفاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1492", section: "الصحابة", category: "الخلفاء", level: "متوسط", question: "من ثاني الخلفاء الراشدين؟", answer: "عمر بن الخطاب رضي الله عنه — ثاني الخلفاء الراشدين، الملقب بالفاروق لتمييزه بين الحق والباطل.", explanation: "يُستفاد منه في باب الخلفاء. يُستفاد منه في باب الخلفاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1493", section: "الصحابة", category: "الخلفاء", level: "متوسط", question: "من ثالث الخلفاء الراشدين؟", answer: "عثمان بن عفان رضي الله عنه — ثالث الخلفاء الراشدين، الملقب بذي النورين لزواجه من ابنتي النبي ﷺ.", explanation: "يُستفاد منه في باب الخلفاء. يُستفاد منه في باب الخلفاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1494", section: "الصحابة", category: "الخلفاء", level: "متوسط", question: "من رابع الخلفاء الراشدين؟", answer: "علي بن أبي طالب رضي الله عنه — رابع الخلفاء الراشدين، وأول الصبيان إسلاماً.", explanation: "يُستفاد منه في باب الخلفاء. يُستفاد منه في باب الخلفاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1495", section: "الصحابة", category: "الألقاب", level: "متوسط", question: "من الصحابي الملقب بذي النورين؟", answer: "عثمان بن عفان رضي الله عنه — الصحابي الملقب بذي النورين لزواجه من رُقية ثم أم كلثوم.", explanation: "يُستفاد منه في باب الألقاب. يُستفاد منه في باب الألقاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1496", section: "الصحابة", category: "الألقاب", level: "متوسط", question: "من الصحابي الملقب بالفاروق؟", answer: "عمر بن الخطاب رضي الله عنه — الصحابي الملقب بالفاروق لفرقته بين الحق والباطل.", explanation: "يُستفاد منه في باب الألقاب. يُستفاد منه في باب الألقاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1497", section: "الصحابة", category: "السيرة", level: "متوسط", question: "من أول الرجال إسلاماً؟", answer: "أبو بكر الصديق رضي الله عنه — أول الرجال إسلاماً، وصدّق النبي ﷺ في الإسراء والمعراج.", explanation: "يُستفاد منه في باب السيرة. يُستفاد منه في باب السيرة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1498", section: "الصحابة", category: "السيرة", level: "متوسط", question: "من أول الصبيان إسلاماً؟", answer: "علي بن أبي طالب رضي الله عنه — أول الصبيان إسلاماً، وابن عم النبي ﷺ وزوج ابنته فاطمة.", explanation: "يُستفاد منه في باب السيرة. يُستفاد منه في باب السيرة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1499", section: "الصحابة", category: "أمهات المؤمنين", level: "متوسط", question: "من أم المؤمنين ابنة أبي بكر؟", answer: "عائشة رضي الله عنها — أم المؤمنين ابنة أبي بكر الصديق، وأكثر الصحابيات روايةً للحديث.", explanation: "يُستفاد منه في باب أمهات المؤمنين. يُستفاد منه في باب أمهات المؤمنين مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1500", section: "الصحابة", category: "الألقاب", level: "متوسط", question: "من الصحابي الملقب بسيف الله المسلول؟", answer: "خالد بن الوليد رضي الله عنه — الصحابي الملقب بسيف الله المسلول لانتصاراته.", explanation: "يُستفاد منه في باب الألقاب. يُستفاد منه في باب الألقاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1501", section: "الصحابة", category: "الألقاب", level: "متوسط", question: "من الصحابي الملقب بأسد الله وأسد رسوله؟", answer: "حمزة بن عبد المطلب رضي الله عنه — عم النبي ﷺ، الملقب بأسد الله وأسد رسوله.", explanation: "يُستفاد منه في باب الألقاب. يُستفاد منه في باب الألقاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1502", section: "الصحابة", category: "الألقاب", level: "متوسط", question: "من الصحابي الملقب بـ (أمين الأمة)؟", answer: "أبو عبيدة عامر بن الجراح رضي الله عنه؛ لقوله ﷺ: «إن لكل أمة أميناً، وإن أميننا أيتها الأمة أبو عبيدة بن الجراح» (البخاري 3744، مسلم 2419)", explanation: "يُستفاد منه في باب الألقاب. يُستفاد منه في باب الألقاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1503", section: "الصحابة", category: "الشهداء", level: "متوسط", question: "من أول شهيدة في الإسلام؟", answer: "سمية بنت خياط أم عمار بن ياسر — أول شهيدة في الإسلام، قُتلت في مكة على يد أبي جهل.", explanation: "يُستفاد منه في باب الشهداء. يُستفاد منه في باب الشهداء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1504", section: "الصحابة", category: "السيرة", level: "سهل", question: "من المؤذن الأول في الإسلام؟", answer: "بلال بن رباح رضي الله عنه — المؤذن الأول في الإسلام، من أهل الحبشة.", explanation: "يُستفاد منه في باب السيرة. يُستفاد منه في باب السيرة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1505", section: "الصحابة", category: "أمهات المؤمنين", level: "متوسط", question: "كم عدد أمهات المؤمنين (زوجات النبي)؟", answer: "توفي رسول الله ﷺ عن تسع، وجملة من دخل بهنّ إحدى عشرة؛ إذ توفيت خديجة بنت خويلد وزينب بنت خزيمة رضي الله عنهما في حياته ﷺ", explanation: "يُستفاد منه في باب أمهات المؤمنين. يُستفاد منه في باب أمهات المؤمنين مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1506", section: "الصحابة", category: "أمهات المؤمنين", level: "سهل", question: "من أول زوجة للنبي ﷺ؟", answer: "خديجة بنت خويلد رضي الله عنها — أول زوجة للنبي ﷺ، وآمنت به قبل غيرها من النساء.", explanation: "يُستفاد منه في باب أمهات المؤمنين. يُستفاد منه في باب أمهات المؤمنين مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1507", section: "الصحابة", category: "أمهات المؤمنين", level: "متوسط", question: "ما الصحابية التي اشتهر عنها لقب «الحميراء»؟", answer: "عائشة رضي الله عنها. وينبغي التنبيه إلى أن هذا اللقب اشتهر في المتأخر من الكتب، وقد نصّ ابن القيم في «المنار المنيف» على أن ما يُروى فيه من الأحاديث لا يثبت، ونحوه عن الذهبي في «سير أعلام النبلاء»", explanation: "يُستفاد منه في باب أمهات المؤمنين. يُستفاد منه في باب أمهات المؤمنين مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1508", section: "الصحابة", category: "الحديث", level: "متوسط", question: "من الصحابية الفقيهة التي كان أكابر الصحابة يرجعون إليها في العلم؟", answer: "عائشة رضي الله عنها؛ قال أبو موسى الأشعري: «ما أشكل علينا أصحابَ رسول الله ﷺ حديثٌ قط فسألنا عائشة إلا وجدنا عندها منه علمًا» (رواه الترمذي). وأما ما يشتهر على الألسنة من عبارة «خذوا نصف دينكم عن هذه الحميراء» فلا أصل له، نصّ على ذلك ابن القيم في «المنار المنيف»", explanation: "يُستفاد منه في باب الحديث. يُستفاد منه في باب الحديث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1509", section: "الصحابة", category: "الشعراء", level: "متوسط", question: "من أشهر شعراء النبي ﷺ الذين كانوا يذبّون عنه؟", answer: "حسان بن ثابت رضي الله عنه، وهو أشهرهم، ومعه كعب بن مالك وعبد الله بن رواحة رضي الله عنهما", explanation: "يُستفاد منه في باب الشعراء. يُستفاد منه في باب الشعراء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1510", section: "الصحابة", category: "السيرة", level: "متوسط", question: "من الأنصاري الذي آخى النبي ﷺ بينه وبين أبي بكر الصديق في المؤاخاة بين المهاجرين والأنصار؟", answer: "خارجة بن زيد بن أبي زهير الأنصاري الخزرجي رضي الله عنه، وكان أبو بكر ينزل عليه بالسُّنح في بني الحارث بن الخزرج", explanation: "يُستفاد منه في باب السيرة. يُستفاد منه في باب السيرة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1511", section: "الصحابة", category: "الكتّاب", level: "متوسط", question: "من أشهر كتّاب الوحي من الصحابة؟", answer: "زيد بن ثابت وأُبيّ بن كعب، والخلفاء الراشدون أبو بكر وعمر وعثمان وعلي، ومعاوية بن أبي سفيان رضي الله عنهم؛ وكتّاب الوحي أكثر من ذلك، وأشهرهم في المدينة زيد بن ثابت", explanation: "يُستفاد منه في باب الكتّاب. يُستفاد منه في باب الكتّاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1512", section: "الصحابة", category: "الألقاب", level: "متوسط", question: "بم لُقِّب عبد الله بن الزبير بن العوام رضي الله عنهما؟", answer: "«عائذ البيت» لاستجارته بالكعبة واعتصامه بحرم الله؛ وهو أول مولود للمهاجرين بالمدينة بعد الهجرة، وأمه أسماء بنت أبي بكر «ذات النطاقين»، وبُويع له بالخلافة فدُعي أمير المؤمنين", explanation: "يُستفاد منه في باب الألقاب. يُستفاد منه في باب الألقاب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1513", section: "الصحابة", category: "السيرة", level: "متوسط", question: "كيف أُعلن تحريم الخمر في المدينة أول مرة حين نزلت آية التحريم؟", answer: "خرج منادٍ لرسول الله ﷺ فنادى في المدينة، ففي حديث أنس بن مالك رضي الله عنه في الصحيحين: «فخرج منادٍ فنادى: ألا إن الخمر قد حُرِّمت»، فأُهريقت الخمر حتى جرت في سكك المدينة. ولم يُسمَّ هذا المنادي في الروايات الصحيحة", explanation: "يُستفاد منه في باب السيرة. يُستفاد منه في باب السيرة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "1514", section: "الصحابة", category: "إسلام الصحابة", level: "متوسط", question: "من الصحابي الذي رُوي أنه خرج يريد النبي ﷺ ثم أسلم في ذلك الخروج؟", answer: "عمر بن الخطاب رضي الله عنه. وقصة خروجه متوشحًا سيفه، ولقائه نعيم بن عبد الله، ودخوله على أخته فاطمة، وقراءته الصحيفة التي فيها سورة طه — إنما هي من رواية أهل السير (ابن إسحاق ومن بعده) لا من الصحيحين، فلا يُجزم بتفاصيلها جزمَ الحديث المرفوع الصحيح. وأما عزّة الإسلام بإسلامه فمما جاء في السنن من دعائه ﷺ: «اللهم أعزّ الإسلام بأحبّ هذين الرجلين إليك: بأبي جهل أو بعمر بن الخطاب» أخرجه الترمذي وابن ماجه من حديث ابن عمر رضي الله عنهما", explanation: "يُستفاد منه في باب إسلام الصحابة. يُستفاد منه في باب إسلام الصحابة مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" }
];

